INSERT INTO products (category_id, name, slug, description, price, stock, image_url, is_available, status, avg_rating, review_count) VALUES
((SELECT id FROM categories WHERE slug = 'cat001'), 'Hawaii mousse', 'p001', 'Bánh mousse vị nhiệt đới với lớp kem mịn, vị xoài và dứa hòa quyện, trang trí lát trái cây tươi mang cảm giác ngày hè trên bãi biển.', 335000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240218/hawaii_mousse_0b7634f35012441cacaf833c24b4a793_master_vmnczf.png', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'Tiramisu cake', 'p002', 'Bánh tiramisu phong cách Ý với lớp kem mascarpone béo ngậy, xen kẽ bánh ladyfinger thấm đẫm cà phê, phủ bột cacao thơm nồng.', 335000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240276/tiramisu_cake_16a01603c84a4217826a59da6c6f6cfd_master_kztodj.jpg', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'Passion fruit & chocolate cake', 'p003', 'Mousse chanh dây chua ngọt nhẹ nhàng kết hợp chocolate đắng dịu, tạo nên hương vị cân bằng, lạ miệng và rất tinh tế.', 335000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240297/passion_fruit___chocolate_cake_81a17ce02408407b8ac29d61cd7abd9b_master_hv1vc0.png', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'Black Forest cake', 'p004', 'Bánh Black Forest với lớp bông lan chocolate ẩm mềm, xen giữa là kem tươi và cherry, phủ chocolate vụn sang trọng.', 325000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240310/060b4193-9b9c-45db-9d42-aaca342699ad_eaebe617eb7e4039992a2fccc3457d76_master_jmlop9.jpg', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'Mango mousse', 'p005', 'Lớp mousse xoài thơm dịu, ngọt thanh, kết hợp đế bánh mềm nhẹ và sốt xoài tươi phía trên, phù hợp cho những ai thích vị trái cây.', 325000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240323/mango_mousse_2025_7f665dc999544e8ab9c7c20d3635b75b_master_itfkng.jpg', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'Seasonal Fruit cake', 'p006', 'Bánh kem trái cây theo mùa với nhiều loại quả tươi đầy màu sắc, lớp kem tươi béo nhẹ giúp cân bằng vị ngọt.', 325000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240375/seasonal_fruit_cake_2e127af76a234fe9b261d154309456ed_master_kgywin.png', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'White cheese and caramel cake', 'p007', 'Bánh phô mai trắng mềm mượt, phủ sốt caramel vàng óng, hương thơm bơ sữa quyện cùng vị ngọt béo đầy hấp dẫn.', 335000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240384/white_cheese_and_caramel_cake_2024_00779bd73b1e4e73b1f987fc1c3d148f_master_ae7ozg.jpg', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'Mango cheese cake', 'p008', 'Đế biscuit giòn nhẹ, kết hợp lớp cream cheese béo mịn và sốt xoài tươi, tạo nên một chiếc cheesecake mát lạnh và sang chảnh.', 345000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240391/mango_cheese_cake_1a48de49feea4aa79b53b9e992125e4c_master_rwuxxt.jpg', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'Passion fruit mousse', 'p009', 'Mousse chanh dây với vị chua thơm đặc trưng, nhẹ nhàng và không gây ngán, thích hợp cho những buổi tiệc trà chiều.', 315000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240364/mango_mousse_2025_7f665dc999544e8ab9c7c20d3635b75b_master_beyerk.jpg', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat001'), 'Yogurt cheese cake', 'p010', 'Bánh lạnh kết hợp sữa chua và phô mai, vị chua nhẹ, béo vừa phải, bề mặt phủ sốt trái cây tươi mát.', 345000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764240334/banh_sua_chua_pho_mai_47fe700fae3d43e68f11307b48a5e8bf_master_ipb6us.jpg', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat002'), 'Bánh hamburger 3pcs', 'p013', 'Set ba chiếc bánh hamburger mini với vỏ mềm, thơm bơ, thích hợp dùng kèm thịt, rau và sốt tùy thích.', 16000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764247076/13_983f4abd084141b6afbaaa0567d88f75_master_g8jcsa.png', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat002'), 'Bánh mì Hàn Quốc mè đen', 'p014', 'Bánh mì mềm xốp với hạt mè đen rang thơm, bên trong nhân ngọt nhẹ, phong cách đường phố Hàn Quốc.', 32000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764247102/banh-my-han-quoc-me-den_3055a3c4a8384158be57025db7d40169_master_fzkklj.png', true, 'ACTIVE', 0, 0),
((SELECT id FROM categories WHERE slug = 'cat002'), 'Bánh mì baguette', 'p015', 'Ổ baguette kiểu Pháp với lớp vỏ giòn rụm, ruột mềm và thơm, rất hợp cho món sandwich hoặc ăn kèm súp.', 15000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764247112/baguette_8b1506303c57446cb46c6ad8fc5d9b5a_master_yddazw.jpg', true, 'ACTIVE', 0, 0),
