((SELECT id FROM categories WHERE slug = 'cat002'), 'Bánh mì đen', 'p017', 'Bánh mì lúa mạch đen tốt cho sức khỏe, vị thơm nhẹ, ít ngọt, phù hợp với thực đơn eat clean.', 15000, 100, 'https://res.cloudinary.com/dektqvylq/image/upload/v1764248533/banh-my-den_ac5853a1b23f4ad8814bc7327e26e11d_master_ahdgkl.png', true, 'ACTIVE', 0, 0),
